package com.shms.entity;
import jakarta.persistence.*;
@Entity @Table(name="wards") public class Ward { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="department_id",nullable=false) private Department department; @Column(nullable=false) private String name; private String floor; private Integer capacity=0; @Enumerated(EnumType.STRING) private Status status=Status.ACTIVE; public enum Status{ACTIVE,INACTIVE} public Long getId(){return id;} public void setId(Long v){id=v;} public Department getDepartment(){return department;} public void setDepartment(Department v){department=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getFloor(){return floor;} public void setFloor(String v){floor=v;} public Integer getCapacity(){return capacity;} public void setCapacity(Integer v){capacity=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} }
